//! THE ROUGH CATALOGUE — `data/catalogue/<slot>.yaml`, the cards of each
//! category the builder does not hold yet (`holds: placeholder` in
//! `data/equipment_slots.yaml`), generated by `scripts/catalogue.py`.
//!
//! NOTHING HERE IS SIMULATED, and no fight reads this module: it lets the page
//! say what a category takes. A card leaves it for a modelled directory the day
//! the engine applies it.

use std::sync::OnceLock;

use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct Card {
    pub id: String,
    pub name: String,
    pub internal_name: String,
    #[serde(default)]
    pub rarity: Option<String>,
    /// Absent on an arcane, which takes no capacity.
    #[serde(default)]
    pub polarity: Option<String>,
    #[serde(default)]
    /// Negative on a Plexus card that hands capacity back.
    pub base_drain: Option<i32>,
    pub max_rank: u32,
    /// DE's card at its top rank, verbatim.
    pub description: crate::prose::Prose,
}

#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct Catalogue {
    /// The equipment slot's id.
    pub slot: String,
    /// What a card is in the game: `mod`, `arcane` or `avionic`.
    pub kind: String,
    pub cards: Vec<Card>,
}

/// Every category's catalogue, in file order.
pub fn all() -> &'static [Catalogue] {
    static C: OnceLock<Vec<Catalogue>> = OnceLock::new();
    C.get_or_init(|| {
        crate::data::files_under("catalogue/")
            .map(|(p, text)| serde_norway::from_str(text).unwrap_or_else(|e| panic!("{p}: {e}")))
            .collect()
    })
}

/// One card, by its `<slot>/<id>` key — the shape the i18n overlay uses.
pub fn by_key(key: &str) -> Option<&'static Card> {
    let (slot, id) = key.split_once('/')?;
    all().iter().find(|c| c.slot == slot)?.cards.iter().find(|c| c.id == id)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_catalogue_belongs_to_a_placeholder_slot_and_names_each_card_once() {
        let slots = crate::data::equipment_slots::all();
        assert!(!all().is_empty());
        for c in all() {
            let s = slots.iter().find(|s| s.id == c.slot).unwrap_or_else(|| panic!("{}: no such slot", c.slot));
            assert_eq!(s.holds, "placeholder", "{}: a held category's cards are modelled, not catalogued", c.slot);
            assert!(["mod", "arcane", "avionic"].contains(&c.kind.as_str()), "{}: kind {}", c.slot, c.kind);
            let mut seen = std::collections::HashSet::new();
            for card in &c.cards {
                assert!(seen.insert(card.id.as_str()), "{}/{} twice", c.slot, card.id);
            }
        }
    }
}
